<script setup>
import {ref,onMounted} from 'vue';import {RefreshCw,Globe} from 'lucide-vue-next';import {useStudio,api} from '../store';
const s=useStudio(),state=ref(null),busy=ref(false),error=ref('');
async function refresh(test=false){busy.value=true;error.value='';try{state.value=await api(test?'network/check':'network/status',test?{}:undefined);}catch(e){error.value=e.message;}finally{busy.value=false;}}onMounted(()=>refresh());
</script>
<template><section class="card"><div class="card-heading"><strong><Globe :size="17"/>网络自动适配</strong></div><div class="settings-body network-settings"><p class="info-note">自动跟随系统代理（包括 Clash Verge）。软件界面、本地模型和本地引擎始终直连；Danbooru、Hugging Face 和线上 API 自动选择可用线路，不修改系统代理设置。</p><label>连接方式<select v-model="s.config.networkMode"><option value="auto">自动跟随系统网络（推荐）</option><option value="direct">外网直接连接</option><option value="proxy">手动指定 HTTP 代理</option></select></label><label v-if="s.config.networkMode==='proxy'">HTTP / 混合代理地址<input v-model="s.config.networkProxy" placeholder="http://127.0.0.1:7897"/></label><div v-if="state" class="translation-provider-list"><span>本机服务：{{state.local}}</span><span>检测到的系统代理：{{state.detectedProxy||'未启用，使用直连'}}</span><span>最近外网连接：{{state.route}}{{state.fallback?' · 已切换备用线路':''}}</span></div><div class="button-row"><button class="secondary" :disabled="busy" :aria-busy="busy" @click="refresh()"><RefreshCw :size="15"/>刷新网络状态</button><button class="secondary" :disabled="busy" @click="refresh(true)"><Globe :size="15"/>检测 Danbooru 连接</button></div><p v-if="error" class="error-note">{{error}}</p><small>修改网络或代理后，会在下一次请求时自动检测；正在下载的任务可点击刷新重新连接。</small></div></section></template>
